{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.Fytika_db_Product_FACEBOOK_CONSOLIDATED_intermediate AS select Adset_Name ,Adset_ID ,FB.ad_id ,FB.ad_name ,\'Facebook Fytika Meta\' as Account_Name ,Account_ID ,Campaign_Name ,Campaign_ID ,split(fb.product_id,\',\')[offset(0)] as product_id ,cast(Fb.date_start as date) Date ,SUM(CLICKS) Clicks ,sum(ifnull(inline_link_clicks,0)) Link_Clicks ,SUM(SPEND) Spend ,SUM(IMPRESSIONS) Impressions ,SUM(ifnull(Fc.Conversions,0)) Conversions ,sum(ifnull(reach,0)) reach ,sum(ifnull(frequency,0)) as frequency ,SUM(ifnull(Fcv.Conversion_Value,0)) Conversion_Value ,sum(ifnull(fd.add_to_carts,0)) Add_to_carts ,sum(ifnull(fdv.add_to_cart_value,0)) Add_to_cart_value ,sum(ifnull(fe.landing_page_views,0)) Landing_page_views ,sum(ifnull(ff.initiate_checkouts,0)) Initiate_checkouts ,sum(ifnull(ffv.initiate_checkouts_value,0)) Initiate_checkouts_value ,\'Facebook\' Channel ,\'Facebook_Custom_Facebook_Marketing_Fytika_db_Meta\' Account from( select * from maplemonk-analytics.maplemonk.Fytika_facebook_ads_product_customcampaigns_data ) FB left join ( select ad_id ,ad_name ,date_start ,SUM(ifnull(cast(JSON_EXTRACT_SCALAR(C,\'$.7d_click\') as FLOAT64),0) + ifnull(cast(JSON_EXTRACT_SCALAR(C,\'$.1d_view\') as FLOAT64),0)) Conversions from maplemonk-analytics.maplemonk.Custom_Facebook_Marketing_Fytika_facebook_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start )Fc ON Fb.ad_id = Fc.ad_id and Fb.date_start=Fc.date_start left join ( select ad_id ,ad_name ,date_start ,SUM(ifnull(cast(JSON_EXTRACT_SCALAR(CV,\'$.7d_click\') as FLOAT64),0) + ifnull(cast(JSON_EXTRACT_SCALAR(CV,\'$.1d_view\') as FLOAT64),0)) Conversion_Value from maplemonk-analytics.maplemonk.Custom_Facebook_Marketing_Fytika_facebook_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start )Fcv ON Fb.ad_id = Fcv.ad_id and Fb.date_start=Fcv.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) add_to_carts from maplemonk-analytics.maplemonk.Custom_Facebook_Marketing_Fytika_facebook_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fd ON Fb.ad_id = Fd.ad_id and Fb.date_start=Fd.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Add_to_cart_Value from maplemonk-analytics.maplemonk.Custom_Facebook_Marketing_Fytika_facebook_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Fdv ON Fb.ad_id = Fdv.ad_id and Fb.date_start=Fdv.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Landing_page_views from maplemonk-analytics.maplemonk.Custom_Facebook_Marketing_Fytika_facebook_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'landing_page_view\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fe ON Fb.ad_id = Fe.ad_id and Fb.date_start=Fe.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Initiate_checkouts from maplemonk-analytics.maplemonk.Custom_Facebook_Marketing_Fytika_facebook_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Ff ON Fb.ad_id = Ff.ad_id and Fb.date_start=Ff.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Initiate_checkouts_Value from maplemonk-analytics.maplemonk.Custom_Facebook_Marketing_Fytika_facebook_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Ffv ON Fb.ad_id = Ffv.ad_id and Fb.date_start=Ffv.date_start group by Adset_Name, split(fb.product_id,\',\')[offset(0)], Adset_ID,fb.ad_id,fb.AD_NAME, Account_Name, Account_ID, Campaign_Name, Campaign_ID,Fb.date_start; CREATE OR REPLACE TABLE maplemonk.Fytika_db_Product_FACEBOOK_CONSOLIDATED as SELECT a.product_id AS PRODUCT_ID, DATE, \'FACEBOOK\' AS Channel, \'FACEBOOK ADS\' AS ACCOUNT, coalesce(d.sku, e.sku, f.sku, g.sku) AS SKU, pm.name as product_name_final, pm.category_name AS PRODUCT_CATEGORY, SUM(spend) AS SPEND, sum(conversion_value) AS SALES from maplemonk.Fytika_db_Product_FACEBOOK_CONSOLIDATED_intermediate a left join ( SELECT LOWER(TRIM(SPLIT(channel_product_id, \'-\')[SAFE_OFFSET(0)])) AS product_id, LOWER(TRIM(sku_code)) AS SKU FROM `maplemonk-analytics.maplemonk.unicommerce_fytika_get_product_listing` where channelname = \'SHOPIFY\' QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(TRIM(SPLIT(channel_product_id, \'-\')[SAFE_OFFSET(0)])) ORDER BY DATE(updated) DESC) = 1 ) d on lower(a.product_id) = lower(d.product_id) left join ( SELECT LOWER(TRIM(SPLIT(channel_product_id, \'-\')[SAFE_OFFSET(1)])) AS variant_id, LOWER(TRIM(sku_code)) AS SKU FROM `maplemonk-analytics.maplemonk.unicommerce_fytika_get_product_listing` where channelname = \'SHOPIFY\' QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(TRIM(SPLIT(channel_product_id, \'-\')[SAFE_OFFSET(1)])) ORDER BY DATE(updated) DESC) = 1 ) e on lower(a.product_id) = lower(e.variant_id) left join ( SELECT LOWER(replace(channel_product_id,\'-\',\'\')) AS product_id, LOWER(TRIM(sku_code))AS SKU FROM `maplemonk-analytics.maplemonk.unicommerce_fytika_get_product_listing` WHERE channelname = \'SHOPIFY\' QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(replace(channel_product_id,\'-\',\'\')) ORDER BY DATE(updated) DESC) = 1 ) f on lower(replace(replace(a.product_id,\'shopify_in\',\'\'),\'_\',\'\')) = lower(f.product_id) left join ( SELECT LOWER(seller_sku_on_channel) AS product_id, LOWER(TRIM(sku_code)) AS SKU FROM `maplemonk-analytics.maplemonk.unicommerce_fytika_get_product_listing` WHERE channelname = \'SHOPIFY\' QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(seller_sku_on_channel) ORDER BY DATE(updated) DESC) = 1 ) g on lower(a.product_id) = lower(g.product_id) left join ( select product_code, name, category_name, mrp, from maplemonk-analytics.maplemonk.unicommerce_fytika_get_product_master qualify row_number() over (partition by product_code order by date(updated) desc) = 1 ) pm on lower(pm.producT_code) = lower(coalesce( d.sku, e.sku,f.sku, g.sku, a.product_id)) group by 1,2,3,4,5,6,7 ;",
                    "transaction": true
                }
            ) }}
